mapper.select:
SELECT ranked.memory_id AS memory_id, ranked.reason AS reason, ranked.content AS content, ranked.created_at AS created_at FROM ( SELECT mr.memory_id AS memory_id, mr.reason AS reason, mr.content AS content, mr.created_at AS created_at, ROW_NUMBER() OVER (PARTITION BY mr.memory_id ORDER BY mr.created_at DESC, mr.id DESC) AS row_num FROM memory_report mr WHERE mr.reviewed_at IS NULL AND mr.memory_id IN
#{memoryId}
) ranked WHERE ranked.row_num <= 5 ORDER BY ranked.memory_id ASC, ranked.row_num ASC
